/** Coordinated portfolio motion. Native scrolling, finite reveals and bounded perspective. */
const query=matchMedia('(prefers-reduced-motion: reduce)');
const toggle=document.querySelector('.motion-switch');
let userPaused=false;try{userPaused=localStorage.getItem('mmm-motion-paused')==='true'}catch{}let disabled=query.matches||userPaused;
const animations=new Set(),scenes=new Set();
const clamp=(n,a=0,b=1)=>Math.min(b,Math.max(a,n));
const ease='cubic-bezier(.22,1,.36,1)';
function play(el,frames,options){if(disabled)return;const a=el.animate(frames,{duration:850,easing:ease,fill:'both',...options});animations.add(a);a.finished.then(()=>animations.delete(a)).catch(()=>animations.delete(a));return a;}
function preference(){disabled=query.matches||userPaused;document.documentElement.classList.toggle('motion-disabled',disabled);toggle.setAttribute('aria-pressed',String(disabled));toggle.setAttribute('aria-label',disabled?'Enable animations':'Pause animations');toggle.querySelector('span').textContent=disabled?'▷':'Ⅱ';toggle.disabled=query.matches;if(disabled){animations.forEach(a=>{try{a.finish()}catch{a.cancel()}});scenes.forEach(el=>{el.style.setProperty('--rx','0deg');el.style.setProperty('--ry','0deg');el.style.setProperty('--reveal-rotate','0deg')});document.querySelector('.hero-media>img')?.style.removeProperty('transform');}schedule();}
toggle.addEventListener('click',()=>{userPaused=!userPaused;try{localStorage.setItem('mmm-motion-paused',String(userPaused))}catch{}preference()});query.addEventListener('change',preference);
// Preserve rich text; split only text nodes, so headings remain one accessible sentence.
const headings=[...document.querySelectorAll('[data-text-reveal]')];
for(const heading of headings){const walker=document.createTreeWalker(heading,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const text of nodes){const fragment=document.createDocumentFragment();for(const part of text.textContent.split(/(\s+)/)){if(!part.trim()){fragment.append(document.createTextNode(part));continue}const mask=document.createElement('span'),inner=document.createElement('span');mask.className='reveal-word';inner.textContent=part;mask.append(inner);fragment.append(mask)}text.replaceWith(fragment)}}
const revealed=new WeakSet();
const revealObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting||revealed.has(entry.target))continue;revealed.add(entry.target);revealObserver.unobserve(entry.target);const words=entry.target.querySelectorAll('.reveal-word>span');if(words.length){words.forEach((word,i)=>play(word,[{transform:'translateY(105%)',opacity:0},{transform:'translateY(0)',opacity:1}],{delay:i*55,duration:950}));}else play(entry.target,[{opacity:0,transform:'translateY(24px)'},{opacity:1,transform:'translateY(0)'}],{duration:800});}},{threshold:.12});
headings.forEach(el=>revealObserver.observe(el));document.querySelectorAll('.statement-grid>div,.project-caption,.growth-offerings article,.approach-line>div,.contact-copy,.founder-bio').forEach(el=>revealObserver.observe(el));
// Real portfolio surfaces carry depth. No decorative 3D mesh or scroll interception.
const depthObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting)scenes.add(entry.target);else scenes.delete(entry.target)}schedule();},{rootMargin:'80px'});
document.querySelectorAll('[data-depth]').forEach(el=>{depthObserver.observe(el);el.addEventListener('pointermove',e=>{if(disabled||e.pointerType!=='mouse')return;const box=el.getBoundingClientRect();const x=(e.clientX-box.left)/box.width-.5,y=(e.clientY-box.top)/box.height-.5;el.style.setProperty('--rx',`${-y*2.4}deg`);el.style.setProperty('--ry',`${x*3}deg`)});el.addEventListener('pointerleave',()=>{el.style.setProperty('--rx','0deg');el.style.setProperty('--ry','0deg')});});
let frame=0;
function schedule(){if(!frame&&!document.hidden)frame=requestAnimationFrame(render)}
function render(){frame=0;const height=document.documentElement.scrollHeight-innerHeight;document.querySelector('.reading-progress').style.transform=`scaleX(${height>0?clamp(scrollY/height):0})`;if(disabled)return;const measurements=[...scenes].map(el=>[el,el.getBoundingClientRect()]);for(const [el,rect]of measurements){if(innerWidth<700){el.style.setProperty('--reveal-rotate','0deg');continue}const enter=clamp((innerHeight-rect.top)/(innerHeight*.8));el.style.setProperty('--reveal-rotate',`${(1-enter)*5}deg`);}const media=document.querySelector('.hero-media>img');if(media){const rect=media.parentElement.getBoundingClientRect();if(rect.bottom>0&&rect.top<innerHeight)media.style.transform=`translateY(${clamp(-rect.top*.1,-35,35)}px) scale(1.04)`}}
addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule,{passive:true});document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(frame);frame=0}else schedule()});
// A deliberate, finite drawing sequence for the conceptual growth framework.
const chart=document.querySelector('.growth-path');if(chart){const chartObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){play(chart.querySelector('.path-line'),[{strokeDashoffset:620},{strokeDashoffset:0}],{duration:1800});chartObserver.disconnect()}},{threshold:.25});chartObserver.observe(chart)}
document.querySelectorAll('[data-stage]').forEach(button=>button.addEventListener('click',()=>{const panel=document.querySelector('#stage-panel');play(panel,[{opacity:.45,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:350})}));
// Responsive previews keep the native image switch and add a finite spatial transition.
document.querySelectorAll('.website-device').forEach(el=>el.addEventListener('pointerdown',()=>{el.style.setProperty('--rx','0deg');el.style.setProperty('--ry','0deg')}));
preference();
